package Practice;

public class Question1Ass3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=-4;
		if(a>0) {
			System.out.println("Positive no.");
		} else if (a%2==0) {
			System.out.println("even no");
		} else if (a%2!=0) {
			System.out.println("odd");
			
		} else {
			System.out.println("zero");
		}
		

	}

}
